  "plans.title": "StockHaven 요금제 비교하기",
  "plans.intro": "어떤 요금제를 선택하시든 하나의 계정을 사용합니다 — Business는 최대 5개의 사업을 포함합니다. 가격은 미국 달러 기준 월 가격이며, 자격이 있는 신규 웹사이트 고객은 Essentials와 Business에 걸쳐 7일 체험 1회를 받을 수 있습니다. 기존 Essentials 구독을 Business로 업그레이드해도 체험이 다시 시작되거나 또 다른 무료 체험이 생성되지 않습니다. 웹사이트 요금제 가격은 적용되는 세금이 있으면 세금 별도입니다. 정확한 청구 금액은 구독을 승인하시기 전에 표시됩니다.",
