  "plans.mobileIncludedNote": "두 웹사이트 요금제 모두 모바일 동반 앱을 포함하므로 웹사이트 구독자는 월 모바일 요금을 함께 지불할 필요가 없습니다.",
  "plans.priceNote": "Essentials는 월 $14.99에 적용되는 세금이 있으면 세금이 추가됩니다. Business는 월 $29.99에 적용되는 세금이 있으면 세금이 추가됩니다. 필요한 세금은 제공업체 결제 시 결정되며 결제 전에 최종 총액에 표시되어야 합니다. 이 비교 페이지는 세금 견적이나 결제 승인이 아닙니다.",
  "plans.mobilePriceNote": "모바일 전용 요금제는 의도된 미국 기본 가격으로 월 $4.99입니다. App Store 또는 Google Play에서 실제 현지 구독 가격과 적용되는 세금을 구매 전에 표시합니다. 제품, 사이트 및 직원 허용량은 웹사이트 등급과 별도로 출시 시 설정됩니다.",
  "plans.planChangeNote": "웹사이트 요금제 변경은 결제 제공업체가 확인해야 합니다. 새 가격, 적용 날짜 및 비례 배분은 변경을 승인하시기 전에 설명됩니다. 업그레이드로 두 번째 구독이 생성되어서는 안 됩니다.",
  "plans.providerNote": "가격, 청구 및 체험은 구독하신 제공업체 — App Store, Google Play, 웹사이트 또는 Shopify — 가 처리하며, 이 페이지가 처리하지 않습니다.",
