  "upgrade.doneUpgradeNow": "Business가 지금 월 $29.99로 시작됩니다. 가격 차액은 다음 청구서에 반영됩니다 — 즉시 청구는 없습니다.",
  "upgrade.doneDowngradeBody": "{date}까지 Business를 유지하며, 그 이후 Essentials가 월 $14.99로 시작됩니다. 다운그레이드에 대한 환불은 없습니다.",
