  "upgrade.previewDowngradeNote": "다운그레이드는 유료 기간이 끝날 때 적용됩니다. 잃게 되는 기능의 데이터는 보관되지만 접근할 수 없습니다 — 다운그레이드의 부작용으로 삭제되지는 않습니다.",
