  "upgrade.upgradeNeverRestartsTrial": "업그레이드해도 무료 체험이 다시 시작되지 않습니다.",
  "upgrade.trialHistoryNote": "Essentials를 결제 중이고 Business로 이동하시면 동일한 고객 계정과 체험 기록을 유지합니다. Business에는 추가 7일 체험이 포함되지 않습니다. 원래 체험이 아직 진행 중일 때 업그레이드하시면 원래 종료 날짜가 재설정되지 않습니다.",
  "upgrade.providerConfirmNote": "요금제 변경은 결제 제공업체의 확인이 필요합니다. 가격 차액, 비례 배분 및 적용 날짜는 변경을 승인하시기 전에 표시되어야 합니다. 업그레이드로 두 번째 동시 구독이 생성되어서는 안 됩니다.",
  "upgrade.chargedThroughProviderNote": "요금제 변경은 결제 제공업체를 통해 청구됩니다. 현재 요금제 아래의 구독 취소 버튼을 사용하거나 설정에서 이 페이지에서 구독을 취소하실 수 있습니다. 취소하면 유료 기간이 끝날 때 향후 갱신이 중단됩니다. 접근이 즉시 종료되지는 않습니다. 기존 무료 워크스페이스는 이러한 옵션을 본다고 해서 청구되지 않습니다.",
  "billing.cancel.title": "구독 취소",
  "billing.cancel.description": "{plan} 구독을 취소합니다. 취소하면 유료 기간이 끝날 때 향후 갱신이 중단됩니다 — 접근이 즉시 종료되지는 않습니다.",
  "billing.cancel.yourPlan": "고객님의 요금제",
  "billing.cancel.doneTitle": "구독이 취소되었습니다.",
  "billing.cancel.doneWithEnd": "{endDate}까지 전체 접근을 유지합니다. 그 날짜 이후에는 {graceDays}일 읽기 전용 유예 기간이 있습니다 — 여전히 로그인하여 제품을 보실 수 있지만, 추가, 편집, 삭제, 스캔, 가져오기, 내보내기 또는 변경을 하실 수 없습니다. {gracePart}",
  "billing.cancel.graceEndsOn": "15일 유예 기간이 {date}에 끝난 후에는 계정과 모든 정보가 영구적으로 삭제되며 복구할 수 없습니다.",
  "billing.cancel.doneNoEnd": "유료 기간이 끝날 때까지 전체 접근을 유지합니다. 그 이후에는 15일 읽기 전용 유예 기간이 적용됩니다. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "첫 유료 청구 후 3일 이내에 취소하셨으므로 첫 결제에 대한 환불 자격이 있을 수 있습니다. 취소 자체로 환불이 발급되지는 않습니다 — {contact}를 통해 요청해 주십시오.",
  "billing.cancel.refundWindowClosed": "취소 자체로 환불이 발급되지는 않습니다. 환불은 첫 번째 성공적인 유료 청구 후 3일 이내에 {contact}를 통해 요청한 경우에만 적용됩니다.",
  "billing.cancel.notCanceledTitle": "구독이 취소되지 않았습니다.",
  "billing.cancel.contactCode": "{contact}에 문의하실 때 이 코드를 언급해 주십시오: {code}",
  "billing.cancel.alreadyCanceledTitle": "이 구독은 이미 취소되었습니다.",
  "billing.cancel.alreadyCanceledWithEnd": "{date}에 종료됩니다. 그때까지 전체 접근을 유지합니다. 그 날짜 이후에는 제품을 볼 수 있는 {graceDays}일 읽기 전용 유예 기간이 있습니다. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "현재 유료 기간이 끝날 때 종료됩니다. 그때까지 전체 접근을 유지합니다.",
  "billing.cancel.appStoreNote": "Google Play 또는 Apple App Store를 통해 구독하시는 경우 해당 스토어의 구독 설정에서 취소해야 할 수 있습니다. 이 대화 상자는 앱 스토어 청구를 중단할 수 없습니다. 앱을 삭제하거나 StockHaven 계정을 삭제해도 스토어 구독이 취소되지는 않습니다.",
  "billing.cancel.trialNote": "체험 중에 취소해도 전체 7일을 유지합니다 — 접근은 {date}에 종료되며 청구되지 않습니다.",
  "billing.cancel.trialNoteNoDate": "체험 중에 취소해도 전체 7일을 유지하며 청구되지 않습니다.",
