  "billing.cancel.endOfPaidPeriod": "유료 기간 종료 시",
  "billing.cancel.keepAccessRest": "취소하면 향후 갱신만 중단됩니다 — 접근이 즉시 종료되지는 않으며, 추가 무료 월이 제공되지 않습니다.",
