  "billing.cancel.gracePeriodRest": "여전히 로그인하여 제품을 보실 수 있으므로, 가지고 있던 것을 살펴보고 기록하실 수 있습니다. 그 외의 모든 기능은 차단됩니다. 추가, 편집, 삭제, 스캔, 가져오기, 내보내기 또는 마이그레이션, 설정, 직원을 사용할 수 없습니다.",
