  "billing.cancelError.businessIdRequired": "어떤 구독을 취소할지 확인할 수 없었습니다. 아무것도 변경되지 않았습니다 — 다시 시도하시거나 지원팀에 문의해 주십시오.",
  "billing.cancelError.subscriptionOwnerRequired": "사업 소유자만 이 구독을 취소할 수 있습니다. 아무것도 변경되지 않았습니다.",
