  "billing.cancelError.eventRequiresReview": "청구 기록을 검토해야 취소할 수 있습니다. 아무것도 변경되지 않았습니다 — 지원팀에 문의해 주십시오.",
  "billing.cancelError.subscriptionCancellationUnavailable": "취소를 완료할 수 없었습니다. 아무것도 변경되지 않았습니다 — 구독과 접근은 이전과 정확히 동일합니다. 다시 시도하시거나 지원팀에 문의해 주십시오.",
  "billing.readiness.ariaLabel": "실제 Essentials 결제 준비 상태",
  "billing.readiness.title": "Essentials 결제 — 실제 계정 안전 점검",
  "billing.readiness.body": "아무것도 구매하지 않고 실제 구독 및 체험 기록을 검사합니다. 무료 Business 계정과 파자마 샘플은 변경되지 않습니다. 이 기능은 Stripe 결제를 열거나, 카드를 청구하거나, 요금제를 변경하지 않습니다.",
  "billing.readiness.checking": "계정 기록을 확인하는 중입니다…",
