  "billing.readiness.ready": "Stripe 결제가 준비되었습니다 — 키, 웹훅 확인 및 증명이 모두 확인되었습니다.",
  "billing.readiness.complimentaryProtected": "무료 Business 워크스페이스가 보호되고 있습니다. 유료 Essentials 테스트 계정이 되어서는 안 됩니다.",
  "billing.readiness.environmentIncomplete": "Stripe 결제 자격 증명, 웹훅 확인 또는 앱 복귀 주소를 모두 확인할 수 없었습니다. 결제를 시작할 수 없습니다.",
  "billing.readiness.ownerHasHistory": "이 소유자는 이전 구독 또는 체험 기록이 있습니다. 두 번째 결제를 생성해서는 안 됩니다.",
  "billing.readiness.trialAlreadyUsed": "소개 체험이 이미 사용되었거나 예약되었습니다. 반복 체험을 시작할 수 없습니다.",
  "billing.readiness.trialEligibilityUnverified": "이 소유자에 대한 1회 체험 자격이 확인되지 않았습니다. 결제가 계속 차단됩니다.",
  "billing.readiness.testModeUnverified": "계정 기록은 읽을 수 있지만, 안전한 Stripe 테스트 모드 격리와 유료 갱신 이행이 확인되지 않았습니다. 결제가 계속 차단됩니다.",
  "billing.readiness.entitlementNotUnique": "기존 요금제 정보가 없거나 모호합니다. 결제를 시작할 수 없습니다.",
