  "billing.readiness.auditUnavailable": "읽기 전용 서버 점검을 사용할 수 없었습니다. 결제나 계정 변경이 발생하지 않았습니다.",
  "billing.dryRun.ariaLabel": "테스트 업그레이드 시뮬레이션",
  "billing.dryRun.title": "Essentials → Business — 연습 시뮬레이션",
