  "exports.eyebrow": "데이터",
  "exports.title": "내보내기 및 백업",
  "exports.subtitleStart": "다운로드는 항상 다음으로 제한됩니다",
  "exports.subtitleRest": ". 모든 파일에는 사업 이름과 만든 날짜가 표시됩니다.",
  "exports.createBusinessFirst": "먼저 사업을 만드십시오 — 내보내기는 앱이 아닌 사업에 속합니다.",
  "exports.lockedTitle": "CSV 및 Excel 내보내기는 Business 기능입니다",
  "exports.lockedDesc": "워크스페이스가 Essentials 요금제를 사용 중입니다. Business는 CSV 및 Excel 내보내기, 재고 평가, 무제한 제품 및 직원, 공급업체, 구매 및 번들을 추가합니다.",
  "exports.seeBusiness": "Business에 포함된 내용 보기",
  "exports.whatTheseAre": "이 파일들이 무엇인지",
  "exports.about1": "모든 데이터셋은 CSV 또는 실제 Excel 통합 문서(.xlsx)로 제공됩니다 — 전체 재고 통합 문서는 Excel 전용이며 데이터셋당 시트가 하나씩 있습니다. CSV 파일은 Excel, Numbers, Google Sheets 및 대부분의 재고 앱에서 열립니다. UTF-8 텍스트, 쉼표 인용, 메모의 줄 바꿈 및 코드의 앞에 오는 0이 모두 보존되며, 수식처럼 시작하는 셀은 스프레드시트에서 텍스트로 열도록 무력화됩니다.",
  "exports.about2": "Excel 파일에서 SKU, UPC, ISBN 및 바코드는 텍스트 셀입니다 — 과학적 표기법으로 표시되지 않으며 0이 잘리지 않고, 열 너비, 헤더 필터 및 통화 또는 수량 형식이 적용됩니다. 전체 재고 통합 문서는 제품, 재고 수준, 위치 및 이동을 별도 시트에 유지합니다.",
  "exports.about3": "매우 큰 내보내기는 데이터셋당 20,000행에서 중단됩니다 — 그런 경우 파일 이름에 그렇게 표시되므로(truncated-20000), 부분 파일이 완전한 파일로 오인되지 않습니다.",
  "exports.about4": "백업은 데이터의 스냅샷이며 원클릭 복원이 아닙니다. 복원은 수동으로 검토를 우선하는 작업이므로 파일을 안전하게 보관하십시오 — 앱에서는 아직 삭제된 사업을 이 파일로 다시 만들 수 없습니다. 앱 코드와 Base44 플랫폼 백업은 이 파일들과 별도로 처리됩니다.",
  "exports.about5": "사진과 첨부 파일은 저장된 링크로 나열됩니다 — 이미지 파일 자체는 다운로드에 포함되지 않습니다.",
  "exports.backupTitle": "전체 백업",
  "exports.backupDesc": "이 사업의 제품, 위치, 재고 수준, 전체 이동 원장, 공급업체, 구매, 주문, 반품, 실사 및 목록과 프로필 설정이 포함된 파일 하나입니다. 직접 관리하는 곳에 보관하십시오.",
  "exports.backupIncludes1": "제품, 코드, 원가 및 메모",
  "exports.backupIncludes2": "위치 및 위치별 수량",
