  "import.createDesc": "아직 카탈로그에 없는 행을 추가합니다. 이미 사용 중인 중복 SKU와 바코드는 건너뛰며, 기초 재고는 선택한 위치에 입고로 반영될 수 있습니다.",
  "import.updateTitle": "기존 제품 업데이트",
  "import.updateDesc": "SKU 또는 레코드 ID로 각 행을 일치시키고 이전 값과 제안된 새 값을 나란히 표시합니다. 빈 셀은 비우도록 요청하지 않는 한 저장된 값을 그대로 두며, 수량은 절대 변경되지 않습니다.",
  "import.receiveModeTitle": "재고 입고",
  "import.receiveModeDesc": "도착한 수량을 한 위치에 추가하고 모든 항목에 대해 이동 원장에 입고를 기록합니다. 각 배치는 표시되므로 동일한 시트를 두 번 입고할 수 없습니다.",
  "import.excelNote": "Excel 통합 문서(.xlsx)는 직접 읽습니다 — 워크시트를 선택하면 열이 자동으로 일치합니다. 코드는 온전히 유지됩니다. 텍스트로 저장된 UPC는 숫자와 앞에 오는 0을 유지합니다. 가져올 수 없는 행은 이유와 함께 나열됩니다",
