  "print.templateIsBusiness": "{label}은(는) Business 기능입니다",
  "print.supplierBlockedDesc": "공급업체 문서는 Business 요금제와 함께 제공됩니다 — 공급업체, 구매 및 발주서입니다. 현재 가지고 있는 모든 것은 계속 작동합니다.",
