  "print.pickCustomerOrderHint": "목록에서 고객 주문을 선택하여 문서를 미리 보십시오.",
  "print.pickReturnHint": "목록에서 기록된 반품을 선택하여 문서를 미리 보십시오.",
  "print.chooseStyleHint": "스타일을 선택한 뒤 목록에서 제품을 선택하십시오. 미리보기에는 프린터에서 나오는 내용이 정확히 표시됩니다.",
  "print.howToReach": "프린터에 연결하는 방법",
  "print.howIntro": "이 앱은 이미 소유하고 있는 프린터에 연결합니다 — 자체가 프린터는 아닙니다. 연결하는 방법은 네 가지가 있으며, 라벨은 어떤 방법으로든 두 요금제 모두에서 인쇄됩니다. 포장 명세서, 발주서, 공급업체 문서 및 보고서는 연결 방법과 관계없이 Business 전용입니다.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "이 페이지에서 데스크톱 Chrome 또는 Edge와 Android Chrome을 사용하는 경우: 라벨 프린터를 선택하면 라벨이 바로 전송됩니다. iOS Safari에서는 작동하지 않습니다 — iPhone에서는 Bluetooth 인쇄가 모바일 앱과 함께 제공됩니다. Zebra ZPL이나 Brother 자체 언어만 이해하는 프린터는 이 페이지가 보내는 라벨을 이해하지 못합니다. 실제 프린터로 확인한 뒤에야 작동한다고 말합니다.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "매장의 Wi-Fi에 프린터를 설치한 뒤 인쇄 버튼을 사용하십시오 — 이 컴퓨터에 설치된 프린터를 통해 매장 네트워크를 거쳐 인쇄됩니다. iPhone에서는 AirPrint가 내장되어 있습니다. 동일한 Wi-Fi에 있는 AirPrint 프린터는 인쇄 시트에 바로 표시되며, 코드도 앱도 필요하지 않고, 앱에 AirPrint 전용 코드도 필요하지 않습니다. 프린터가 AirPrint를 지원해야 하며(대부분의 새 프린터가 지원합니다) 휴대폰과 프린터가 동일한 Wi-Fi에 있어야 합니다.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Ethernet 코드로 프린터를 매장 네트워크에 연결하고, 컴퓨터에 설치한 뒤, 인쇄 버튼을 통해 인쇄하십시오. Ethernet은 데스크톱 및 컴퓨터용 경로입니다 — iPhone은 Ethernet 코드를 사용하지 않습니다.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "프린터를 코드로 컴퓨터에 연결하고 인쇄 버튼을 사용하십시오 — 거기에 설치된 프린터를 통해 인쇄됩니다. USB OTG 케이블이 있는 Android 휴대폰에서는 위의 USB 버튼이 프린터와 직접 통신합니다. iPhone은 USB로 직접 인쇄할 수 없습니다 — WebUSB가 없습니다 — 따라서 Wi-Fi / AirPrint를 사용하거나 모바일 앱에서 Bluetooth를 사용하십시오.",
  "print.howCordsLead": "코드는 한 단계 떨어져서도 iPhone에 사용됩니다.",
  "print.howCordsBody": "매장 컴퓨터에 연결된 USB 프린터나 네트워크에 연결된 Ethernet 프린터는 매장 Wi-Fi를 통해 iPhone에 표시됩니다(AirPrint / 공유 프린터) — 코드는 프린터를 네트워크에 견고하게 연결하고, 휴대폰은 무선으로 연결합니다.",
  "print.howOfflineLead": "인터넷이 끊기면,",
  "print.howOfflineBody": "이 페이지에 이미 있는 라벨과 문서는 여전히 인쇄됩니다 — 인쇄 버튼, 라벨 PDF, Bluetooth 및 USB는 연결이 필요하지 않습니다. 인터넷이 필요한 것은 페이지와 제품을 처음 로드하는 것입니다. 완전한 오프라인 모드(연결 없이 앱에서 작업하기)는 별도의 더 큰 작업이며 여기에서는 주장하지 않습니다.",
