  "settings.cancelSubscription": "구독 취소",
  "settings.cancelTerms.appleLink": "Apple 취소 안내",
  "settings.cancelTerms.googlePlayLink": "Google Play 취소 안내",
  "settings.cancelTerms.graceTitle": "유료 기간이 끝난 후 — 15일 유예, 그다음 삭제:",
  "settings.cancelTerms.intro": "이는 유료 Luminous StockHaven 구독에 대한 약관입니다. 웹사이트 구독 청구는 Stripe를 통해 이루어집니다. 아래 구독 취소 버튼을 사용하여 언제든지 직접 구독을 취소하실 수 있습니다 — 직원 승인이 필요하지 않습니다. 취소 및 환불 요청은 공식 고객 지원 연락처인 theluminousbookshop@outlook.com을 통해서도 처리할 수 있습니다.",
  "settings.cancelTerms.noApprovalBody": "언제든지 직접 구독을 취소하실 수 있습니다. 직원 승인이 필요하지 않습니다. 향후 갱신은 결제 제공업체가 취소를 확인한 뒤에만 중단됩니다.",
  "settings.cancelTerms.noApprovalTitle": "승인 없이 취소:",
  "settings.cancelTerms.paymentBody": "유료 체험의 경우, 7일 체험은 가입 시 결제 수단이 필요합니다. 해당 체험 취소 마감일 이내에 취소하지 않으면 선택한 월 요금제가 체험 후 자동으로 청구됩니다. 가격, 첫 청구 날짜 및 제공업체별 취소 마감일은 가입 중에 표시되어야 합니다. 체험 청구는 Stripe를 통해 이루어집니다.",
  "settings.cancelTerms.paymentTitle": "결제 수단 및 자동 갱신:",
  "settings.cancelTerms.remainingBody": "이미 청구 기간에 대해 지불하셨다면, 확인된 유료 기간 종료 날짜까지 접근을 유지하실 수 있습니다. 조기 종료는 적절한 제공업체 확인과 해당 환불 처리가 필요합니다. 무료 체험 접근은 제공업체가 확인한 체험 종료 날짜에 따라 종료됩니다.",
  "settings.cancelTerms.remainingTitle": "남은 접근:",
  "settings.cancelTerms.storesBody": "Google Play 또는 Apple App Store를 통해 구독하시는 경우, 구독은 해당 스토어가 청구하고 관리합니다. 구독에 사용한 동일한 Google 또는 Apple 계정의 구독 섹션에서 직접 취소해야 할 수 있습니다. 별도의 웹사이트 구독을 취소하거나, 이 앱을 삭제하거나, Luminous StockHaven 계정 삭제를 요청해도 스토어 청구 구독이 자동으로 취소되지는 않습니다. 누가 청구하는지 확인하려면 구매 영수증을 확인하십시오.",
  "settings.cancelTerms.storesTitle": "Google Play 및 Apple App Store 구독(스토어를 통해 구독하시는 경우):",
  "settings.cancelTerms.title": "취소 약관 및 조건",
  "settings.cancelTerms.trialBody": "7일 체험은 자격이 있는 고객당 한 번만 사용할 수 있습니다. 체험이나 구독을 취소해도 또 다른 체험이 부여되지 않습니다. 재가입 고객은 유료 구독을 선택해야 합니다.",
  "settings.cancelTerms.trialTitle": "무료 체험 1회:",
  "settings.canceled.endsOn": "이 구독은 취소되었으며 {date}에 종료됩니다. 그때까지 전체 접근을 유지합니다.",
  "settings.delete.checking": "기존 삭제 요청을 확인하는 중입니다…",
  "settings.delete.description": "Luminous StockHaven 로그인 계정 제거를 요청합니다.",
  "settings.delete.dialogDescription": "이는 계정 삭제 검토를 요청합니다. 로그인이나 재고를 즉시 제거하지 않으며, Stripe 구독을 취소하지도 않습니다. 요청을 제출하시려면 {word}를 입력하여 확인해 주십시오.",
