  "settings.pastDue.body": "마지막 결제가 처리되지 않았습니다. 업그레이드 페이지에서 결제 수단을 업데이트하십시오 — Stripe가 자체 일정에 따라 다시 시도하며 구독이 조기에 취소되지 않습니다. 무엇을 해야 할지 확실하지 않으시면 theluminousbookshop@outlook.com으로 지원팀에 문의해 주십시오.",
