  "settings.trial.cancelKeeps": "체험 중에 취소해도 전체 7일을 유지합니다 — 접근은 {date}에 종료되며 청구되지 않습니다.",
  "staff.access.noSeatBody": "계정에 이 사업에 대한 직원 좌석이 없으므로 재고가 닫혀 있습니다. 소유자에게 직원 및 역할에서 추가해 달라고 요청하십시오.",
  "staff.access.noSeatTitle": "이 사업은 고객님의 로그인에 열려 있지 않습니다",
  "staff.access.pendingBody": "이 사업에는 아직 활성화되지 않은 고객님의 이메일에 대한 초대가 있습니다. 소유자에게 직원 상태를 활성으로 설정해 달라고 요청하십시오. 그때까지는 여기에 아무것도 표시되지 않습니다.",
  "staff.access.pendingTitle": "초대가 아직 활성화되지 않았습니다",
  "staff.access.signOut": "로그아웃",
  "staff.access.suspendedBody": "관리자가 활성 사업에 대한 이 직원 계정을 일시 중지했습니다. 다시 활성으로 설정해 달라고 요청한 뒤 다시 로그인하십시오.",
  "staff.access.suspendedTitle": "접근이 일시 중지되었습니다",
  "staff.addFirst": "첫 직원 추가하기",
  "staff.addMember": "직원 추가",
  "staff.emptyBody": "사람을 추가하고, 역할을 부여하고, 그에 따른 권한을 부여하면, 이메일로 초대되어 이 사업에 로그인할 수 있습니다.",
  "staff.emptyTitle": "아직 직원이 없습니다",
  "staff.eyebrow": "팀",
  "staff.how.p1": "모든 구성원은 역할과 자체 권한 목록을 가지고 있으므로, 역할에서 시작하여 새 역할을 만들지 않고 한 가지를 변경할 수 있습니다. 역할을 편집해도 이미 해당 역할을 가진 구성원이 다시 작성되지는 않습니다 — 구성원을 열어 역할 기본값을 다시 적용하십시오.",
  "staff.how.p2": "사용자 지정 역할은 Business 기능입니다. Essentials는 5가지 기본 제공 역할(소유자, 관리자, 재고 담당자, 판매 담당자, 조회자)을 사용합니다.",
  "staff.how.p3": "초대는 이메일로 전송됩니다. 구성원은 수락한 뒤에만 로그인할 수 있으며, 이 목록에서 누군가를 제거해도 앱 계정이 삭제되지는 않습니다.",
  "staff.how.p4": "매장은 사람이 배정된 위치입니다. 카드에 기록되며, 열 수 있는 항목은 여전히 역할과 권한에 따라 결정됩니다.",
  "staff.how.p5": "권한은 각 사람이 열 수 있는 항목을 결정합니다. 역할 밖에 있는 메뉴 항목은 숨겨지며, 차단된 주소는 페이지 대신 “역할에 없음” 알림을 표시합니다. 변경 사항은 해당 사람이 다음에 앱을 로드할 때 적용됩니다. 구성원을 일시 중지하면 완전히 잠깁니다.",
  "staff.how.p6": "관리자는 모든 데이터를 보고 변경할 수 있고, 앱 사용자와 역할을 관리할 수 있으며, 직원 역할에 의해 제한되지 않습니다. 직원 기록이 없는 사람 — 새 사업의 소유자 — 은 전체 접근 권한을 유지합니다.",
  "staff.howTitle": "직원과 역할이 작동하는 방식",
  "staff.limitBadgeLabel": "직원",
  "staff.loading": "직원을 불러오는 중입니다…",
