  "payroll.dd.steps.body": "1. ACH 결제를 보낼 수 있는 사업용 은행 계좌가 필요합니다. 2. 각 팀원에게서 서명된 승인 양식을 받아 주십시오 — 무효 수표가 있으면 번호를 확인하는 데 도움이 됩니다. 3. 돈이 제때 도착하도록 급여일 2-3영업일 전에 급여를 보내 주십시오. 4. 대부분의 주에서는 팀원의 서면 동의가 필요합니다. 이 앱은 양식을 수집하고 단계를 안내합니다 — 실제로 돈을 보내는 일은 본인의 은행을 통해 이루어집니다.",
