  "settings.security.genericError": "문제가 발생했습니다. 다시 시도해 주십시오.",
  "settings.security.accountEmail": "계정 이메일",
  "settings.security.backupCodesTitle": "백업 코드",
  "settings.security.backupCodesDesc": "일회용 예비 키입니다. 인쇄하거나 적어 두어 안전한 곳에 보관해 주십시오 — 이메일을 잃었을 때 각 코드로 한 번씩 돌아올 수 있습니다.",
  "settings.security.codesRemaining": "남은 미사용 백업 코드: {count}개",
