  "settings.security.newCodesTitle": "새 백업 코드",
  "settings.security.codesOnceWarning": "이 코드는 한 번만 표시됩니다 — 저희는 뒤섞인 사본만 보관하므로, 저희도 다시 보여 드릴 수 없습니다. 새 세트를 생성하면 이전의 모든 코드가 취소됩니다.",
  "settings.security.printCodes": "이 코드 인쇄",
