  "rewards.voided": "보상이 무효 처리되었습니다.",
  "workforce.tab.rewards": "보상",
  "training.lessons.mgr-give-rewards.step1": "인력 관리를 열고 보상을 눌러 주십시오. 팀원을 선택한 뒤 종류를 선택해 주십시오. 매장 할인, 기프트 카드, 또는 본인의 말로 설명하는 기타입니다.",
  "training.lessons.mgr-give-rewards.step2": "보상에 짧은 이름을 붙이고 원하시면 메모를 남겨 주십시오. 해당 직원은 즉시 알림을 받고, 보상은 자체 코드를 가지고 내 보상에 기다립니다.",
  "training.lessons.mgr-give-rewards.step3": "설계된 경계는 이렇습니다. 본인은 직원에게만 보상할 수 있습니다. 본인이나 다른 관리자에게는 보상할 수 없습니다 — 관리자에게 보상하는 것은 소유자의 결정이며, 앱은 솔직하게 거부합니다.",
  "training.lessons.mgr-give-rewards.step4": "계산대에서는 팀원이 보여 주는 코드를 입력하고 사용됨으로 표시해 주십시오 — 각 코드는 한 번만 작동합니다. 계획이 변경되면 본인이 준 보상을 무효 처리할 수 있습니다. 소유자의 선물은 소유자가 무효 처리합니다.",
  "training.lessons.mgr-give-rewards.title": "직원에게 보상 주기",
  "training.lessons.owner-give-rewards.step1": "보상은 인력 관리의 보상 탭에 있으며, Business 요금제 전용입니다 — Essentials에서는 탭에 잠긴 문이 표시되어, 팀이 더 큰 요금제에 무엇이 있는지 볼 수 있습니다.",
  "training.lessons.owner-give-rewards.step2": "팀의 누구에게나 보상할 수 있습니다 — 직원과 관리자 모두입니다. 직원을 선택한 뒤 종류를 선택해 주십시오. 매장 할인(원하는 할인율), 어디에서든 쓸 수 있는 기프트 카드, 또는 본인의 말로 설명하는 어떤 인센티브든 가능합니다.",
  "training.lessons.owner-give-rewards.step3": "보상은 자체 일회용 코드와 함께 도착하고 해당 직원의 알림 종을 울립니다. 직원은 계산대에서 코드를 보여 주고, 소유자나 관리자가 입력해 사용됨으로 표시합니다.",
  "training.lessons.owner-give-rewards.step4": "인쇄되거나 공유되는 보상 전표에는 본인 사업의 이름만 들어갑니다 — 앱의 이름은 절대 들어가지 않습니다. 매장의 감사 인사이지, 광고가 아닙니다.",
  "training.lessons.owner-give-rewards.title": "보상 주기(Business 요금제)",
  "training.lessons.owner-rewards-oversight.step1": "관리자도 보상할 수 있습니다 — 직원에게만입니다. 앱은 관리자가 본인이나 다른 관리자에게 보상하는 것을 거부합니다. 관리자에게 보상하는 것은 항상 본인의 결정입니다.",
  "training.lessons.owner-rewards-oversight.step2": "사업의 모든 보상을 보상 기록에서 볼 수 있습니다. 누가 주었는지, 누가 받았는지, 준비 완료인지 사용됨인지 무효인지입니다. 관리자는 본인이 준 보상과 받은 보상만 봅니다.",
  "training.lessons.owner-rewards-oversight.step3": "관리자가 준 보상을 포함해 어떤 보상이든 무효 처리할 수 있습니다. 관리자는 본인의 선물을 무효 처리할 수 있지만, 본인의 선물은 절대 무효 처리할 수 없습니다.",
  "training.lessons.owner-rewards-oversight.step4": "각 코드는 정확히 한 번만 작동하며, 무효 처리된 보상은 절대 사용할 수 없습니다 — 기록에는 항상 보상이 어떻게 끝났는지 표시됩니다.",
  "training.lessons.owner-rewards-oversight.title": "보상 감독하기: 관리자의 지급",
  "training.lessons.staff-your-rewards.step1": "관리자나 소유자가 보상을 주면 알림 종이 울립니다. 인력 관리를 열고 보상을 누르면 내 보상 아래에서 볼 수 있습니다.",
  "training.lessons.staff-your-rewards.step2": "모든 보상에는 자체 코드가 있습니다. 코드를 본인만 간직해 주십시오 — 계산대에서 코드를 보여 주는 사람이 보상을 사용합니다.",
  "training.lessons.staff-your-rewards.step3": "사용하려면 구매할 때 코드를 보여 주십시오. 계산대에 있는 사람이 입력하고 사용됨으로 표시합니다 — 각 코드는 정확히 한 번만 작동합니다.",
  "training.lessons.staff-your-rewards.step4": "보상은 Business 요금제의 특전입니다. 매장이 Business가 아니라면 보상 탭에는 대신 잠긴 문이 표시됩니다 — 그것이 요금제의 내용이지, 실수가 아닙니다.",
  "training.lessons.staff-your-rewards.title": "내 보상: 코드 찾기와 사용하기",
