  "pos.shopify.help": "Shopify POS 판매는 Shopify 주문입니다. 이 매장을 연결하면 모든 주문이 스스로 여기에서 재고를 차감합니다.",
  "pos.shopify.tokenNote": "토큰은 Shopify 관리자의 맞춤 앱에서 옵니다. 서버에만 저장되며 다시 표시되지 않습니다.",
  "pos.shopify.tokenPlaceholder": "Shopify 맞춤 앱의 접근 토큰",
